// Password criptograficamente segura (politica del handoff): sin
// caracteres ambiguos, 12 + 1 simbolo, barajada con crypto.
const crypto = require('crypto');
const b = $input.first().json.body || {};
const email = (b.email || '').trim().toLowerCase();
if (!email || email.indexOf('@') < 1) throw new Error('email requerido');
const AL = 'ABCDEFGHJKMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789';
const SIM = '!@#$%*?';
const pick = (set, n) => Array.from(crypto.randomBytes(n)).map(x => set[x % set.length]).join('');
const bruto = pick(AL, 12) + pick(SIM, 1);
const password = bruto.split('').map(c => ({ c, o: crypto.randomInt(1e6) }))
  .sort((a, z) => a.o - z.o).map(x => x.c).join('');
return [{ json: { email, nombre: b.nombre || b.name || '', lang: (b.lang || b.idioma) === 'en' ? 'en' : 'es', password } }];
